// Synthetic authority and signed observation fixture; exercise real bounded chain and staging.
// No HTTP dispatch, model calls, live owner approval, or production writes.
import {readFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import assert from 'node:assert/strict';
const initial=readFileSync('sql/reality-final-loop-interrupted-obligation-qualification-v1.sql','utf8');
const bounded=readFileSync('sql/reality-final-loop-bounded-same-obligation-claim-v1.sql','utf8');
const all=readFileSync('sql/reality-final-loop-chat-recovery-receipt-continuation-v1.sql','utf8');
const extract=(name)=>{const from=all.indexOf('CREATE OR REPLACE FUNCTION '+name+'(');assert.ok(from>=0,name);const end=all.indexOf('\nCREATE OR REPLACE FUNCTION ',from+1);return all.slice(from,end<0?all.length:end)};
const chat=extract('public.reality_read_owner_final_loop_child_approvals_v1');
const chain=extract('reality_internal.read_final_loop_bounded_release_chain_v1');
const stage=extract('reality_internal.stage_final_loop_bounded_recovery_continuation_v1');
const setup="\nBEGIN;\nDO $$ BEGIN\n IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon;END IF;\n IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated;END IF;\n IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN CREATE ROLE service_role;END IF;\nEND $$;\nCREATE SCHEMA reality_internal;\nGRANT USAGE ON SCHEMA reality_internal TO service_role;\nCREATE TABLE reality_internal.final_loop_pr_source_plans_v1(plan_id uuid PRIMARY KEY,owner_id uuid,shift_id uuid,parent_original_work_id text,\n source_ref text,source_head_sha text,source_manifest_sha256 text,source_plan jsonb,proposed_scope_count integer,file_count integer);\nCREATE TABLE reality_internal.final_loop_child_approval_packets_v1(packet_id uuid PRIMARY KEY,plan_id uuid,owner_id uuid,shift_id uuid,\n parent_original_work_id text,source_ref text,source_manifest_sha256 text,acceptance_contract_sha256 text,authority_effect text,\n state text,owner_approval_receipt_sha256 text,proposal_fingerprint text,created_at timestamptz);\nCREATE TABLE reality_internal.final_loop_child_review_work_v1(child_work_id text PRIMARY KEY,plan_id uuid,packet_id uuid,owner_id uuid,shift_id uuid,\n parent_original_work_id text,scope_index integer,scope_sha256 text,source_manifest_sha256 text,source_head_sha text,acceptance_contract_sha256 text,\n phase text,claimant_worker_run_id uuid,canonical_prepare_invocation_id uuid,canonical_verify_invocation_id uuid,canonical_verify_invocation_run_id uuid,\n independent_verifier_run_id uuid,independent_review_receipt_sha256 text,verifier_evidence jsonb,advisory_rejection_receipts jsonb,\n model_response_id text,review_body text,review_sha256 text);\nCREATE TABLE reality_internal.signed_worker_actual_runs_v1(run_id uuid PRIMARY KEY,status text,started_at timestamptz,finished_at timestamptz);\nCREATE TABLE reality_internal.final_loop_parent_integration_batches_v1(plan_id uuid,packet_id uuid,owner_id uuid,shift_id uuid,\n parent_original_work_id text,source_manifest_sha256 text,source_head_sha text,acceptance_contract_sha256 text,\n batch_index int,phase text,cross_scope_receipt_sha256 text,evidence jsonb,first_scope_index int,last_scope_index int,\n verifier_worker_run_id uuid,verified_child_receipts_sha256 text);\nCREATE TABLE reality_internal.owner_continuity_qualification_routes_v1(owner_id uuid,source_ref text,intake_family text,\n reconciliation_snapshot jsonb,reconciliation_receipt_sha256 text,reconciliation_checked_at timestamptz);\nCREATE TABLE reality_internal.final_loop_resume_events_v1(shift_id uuid,state text);\nCREATE TABLE reality_internal.governed_employee_shifts_v1(shift_id uuid,owner_id uuid,closed_at timestamptz);\nCREATE TABLE public.recovery_fixture(shift_id uuid PRIMARY KEY,guard jsonb);\nCREATE FUNCTION public.reality_read_final_loop_shared_continuity_guard_v1(uuid) RETURNS jsonb LANGUAGE sql AS\n 'SELECT guard FROM public.recovery_fixture WHERE shift_id=$1';\nCREATE FUNCTION reality_internal.final_loop_pr_review_acceptance_digest_v1(uuid) RETURNS text LANGUAGE sql AS\n 'SELECT acceptance_contract_sha256 FROM reality_internal.final_loop_child_approval_packets_v1 WHERE plan_id=$1';\nGRANT SELECT ON ALL TABLES IN SCHEMA reality_internal TO service_role;\nGRANT SELECT ON public.recovery_fixture TO service_role;\n\nALTER TABLE reality_internal.final_loop_child_review_work_v1 ADD COLUMN claim_id uuid NOT NULL DEFAULT gen_random_uuid(),\n ADD COLUMN claimed_at timestamptz,ADD COLUMN updated_at timestamptz DEFAULT clock_timestamp(),ADD COLUMN premodel_recovery_count smallint NOT NULL DEFAULT 1,\n ADD COLUMN independent_provider_evidence_sha256 text,ADD COLUMN verified_at timestamptz;\nALTER TABLE reality_internal.final_loop_child_approval_packets_v1 ADD COLUMN approved_at timestamptz,ADD COLUMN owner_approval_request_id uuid;\nALTER TABLE reality_internal.final_loop_pr_source_plans_v1 ADD COLUMN source_proof_sha256 text,ADD COLUMN state text;\nALTER TABLE reality_internal.governed_employee_shifts_v1 ADD COLUMN authorized_at timestamptz,ADD COLUMN planned_end_at timestamptz,\n ADD COLUMN status text,ADD COLUMN plan_fingerprint text;\nCREATE TABLE reality_internal.governed_employee_completion_warrants_v1(shift_id uuid,owner_id uuid,plan_fingerprint text,state text,mode text,source_scope jsonb);\nCREATE TABLE reality_internal.riley_pr_review_originals_v1(shift_id uuid,owner_id uuid,original_work_id text,source_ref text,phase text,\n model_response_id text,review_body text,provider_comment_id bigint,settlement_receipt_id uuid);\nGRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA reality_internal TO service_role;\nCREATE FUNCTION public.reality_read_final_loop_child_approval_preflight_v1(uuid) RETURNS jsonb LANGUAGE sql AS\n 'SELECT jsonb_build_object(''plans'',jsonb_agg(jsonb_build_object(''plan_id'',p.plan_id,''independent_goal_acceptance_verified'',true,''owner_approval_claim_window_current'',true))) FROM reality_internal.final_loop_pr_source_plans_v1 p WHERE shift_id=$1';\n-- Synthetic exact signed-run/continuity witness. Production scope validator\n-- remains unchanged; this fixture tests the downstream real allocator/fence.\nCREATE FUNCTION reality_internal.check_final_loop_canonical_child_scope_v1(uuid,uuid,jsonb) RETURNS jsonb LANGUAGE sql AS\n 'SELECT jsonb_build_object(''status'',CASE WHEN EXISTS(SELECT 1 FROM reality_internal.signed_worker_actual_runs_v1 WHERE run_id=$2 AND status=''STARTED'' AND finished_at IS NULL) AND EXISTS(SELECT 1 FROM public.recovery_fixture f WHERE f.shift_id=$1 AND f.guard->>''continuity_head_sha256''=$3->>''continuity_head_sha256'') THEN ''FINAL_LOOP_CANONICAL_CHILD_SCOPE_CURRENT'' ELSE ''FINAL_LOOP_CANONICAL_SCOPE_DENIED'' END)';\nCREATE OR REPLACE FUNCTION reality_internal.final_loop_canonical_child_matches_v1(p_child_work_id text, h jsonb)\n RETURNS boolean\n LANGUAGE sql\n STABLE\n SET search_path TO ''\nAS $function$\n SELECT EXISTS(SELECT 1 FROM reality_internal.final_loop_child_review_work_v1 c\n  JOIN reality_internal.final_loop_pr_source_plans_v1 p ON p.plan_id=c.plan_id\n  WHERE c.child_work_id=p_child_work_id AND c.owner_id::text=h->>'owner_id'\n   AND c.shift_id::text=h->>'shift_id' AND c.packet_id::text=h->>'packet_id'\n   AND c.plan_id::text=h->>'plan_id' AND c.parent_original_work_id=h->>'parent_original_work_id'\n   AND c.source_manifest_sha256=h->>'source_manifest_sha256'\n   AND c.source_head_sha=h->>'source_head_sha'\n   AND c.acceptance_contract_sha256=h->>'acceptance_contract_sha256'\n   AND p.source_ref=h->>'source_ref' AND p.source_proof_sha256=h->>'source_proof_sha256'\n   AND EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(h->'scope_fingerprints') x\n    WHERE x->>'index'=c.scope_index::text AND x->>'scope_sha256'=c.scope_sha256))\n$function$;\nCREATE OR REPLACE FUNCTION public.reality_claim_final_loop_child_review_v1(p_shift_id uuid, p_worker_run_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE v_packet record;v_plan record;v_parent record;v_child record;\n v_scope jsonb;v_expected integer;v_actual integer;v_work text;\nBEGIN\n IF current_user<>'service_role' THEN\n  RAISE EXCEPTION 'FINAL_LOOP_CHILD_CLAIM_SERVICE_ONLY';END IF;\n IF p_shift_id IS NULL OR p_worker_run_id IS NULL OR\n  NOT EXISTS(SELECT 1 FROM reality_internal.signed_worker_actual_runs_v1 r\n   WHERE r.run_id=p_worker_run_id AND r.status='STARTED'\n    AND r.finished_at IS NULL AND\n    r.started_at>=pg_catalog.clock_timestamp()-interval '10 minutes') THEN\n  RETURN pg_catalog.jsonb_build_object(\n   'status','FINAL_LOOP_CHILD_SIGNED_WORKER_REQUIRED',\n   'child_claimed',false,'original_job_completed',false);END IF;\n SELECT a.* INTO v_packet FROM\n  reality_internal.final_loop_child_approval_packets_v1 a\n JOIN reality_internal.governed_employee_shifts_v1 s\n  ON s.shift_id=a.shift_id AND s.owner_id=a.owner_id\n JOIN reality_internal.governed_employee_completion_warrants_v1 w\n  ON w.shift_id=s.shift_id AND w.owner_id=s.owner_id\n  AND w.plan_fingerprint=s.plan_fingerprint\n WHERE a.shift_id=p_shift_id\n  AND a.state IN ('APPROVED_ONCE','EFFECT_RESERVED_RECONCILE_ONLY')\n  AND a.owner_approval_receipt_sha256 ~ '^sha256:[a-f0-9]{64}$'\n  -- Owner intent is durable for the exact active signed shift. The separate\n  -- actual worker lease above remains short-lived and must be current.\n  AND a.approved_at IS NOT NULL\n  AND a.approved_at<=pg_catalog.clock_timestamp()\n  AND a.owner_approval_request_id IS NOT NULL\n  AND s.closed_at IS NULL AND s.authorized_at IS NOT NULL\n  AND s.planned_end_at='infinity'::timestamptz\n  AND s.status IN ('RUNNING','AWAITING_EXACT_ORIGINAL_WORK')\n  AND w.state='ACTIVE' AND w.mode IN ('UNTIL_ALL_INDEPENDENT_FINAL_RECEIPTS',\n   'UNTIL_ALL_INDEPENDENT_INTERNAL_MAINTENANCE_RECEIPTS')\n  AND EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(w.source_scope) scope(entry)\n   WHERE scope.entry->>'source_ref'=a.source_ref)\n  AND EXISTS(SELECT 1 FROM reality_internal.riley_pr_review_originals_v1 r\n   WHERE r.shift_id=a.shift_id AND r.owner_id=a.owner_id\n    AND r.original_work_id=a.parent_original_work_id\n    AND r.source_ref=a.source_ref AND r.phase='BLOCKED'\n    AND r.model_response_id IS NULL AND r.review_body IS NULL\n    AND r.provider_comment_id IS NULL\n    AND r.settlement_receipt_id IS NULL)\n ORDER BY a.approved_at,a.packet_id LIMIT 1 FOR UPDATE OF a SKIP LOCKED;\n IF NOT FOUND THEN\n  RETURN pg_catalog.jsonb_build_object(\n   'status','FINAL_LOOP_NO_OWNER_APPROVED_PARENT_CHILD_REVIEW_READY',\n   'child_claimed',false,'original_job_completed',false);END IF;\n SELECT * INTO v_plan FROM\n  reality_internal.final_loop_pr_source_plans_v1 p\n WHERE p.plan_id=v_packet.plan_id AND p.shift_id=v_packet.shift_id\n  AND p.owner_id=v_packet.owner_id\n  AND p.parent_original_work_id=v_packet.parent_original_work_id\n  AND p.source_ref=v_packet.source_ref\n  AND p.source_manifest_sha256=v_packet.source_manifest_sha256\n  AND p.state='PROPOSED_SOURCE_PLAN_AWAITING_INDEPENDENT_ADMISSION';\n IF NOT FOUND THEN\n  RETURN pg_catalog.jsonb_build_object('status','FINAL_LOOP_PARENT_PLAN_DRIFT',\n   'child_claimed',false,'original_job_completed',false);END IF;\n -- Revalidate the exact frozen contract and independently recorded goal\n -- before reserving any child. Durable consent does not permit scope drift.\n IF v_packet.acceptance_contract_sha256 IS DISTINCT FROM\n   reality_internal.final_loop_pr_review_acceptance_digest_v1(v_plan.plan_id)\n   OR NOT EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(\n    public.reality_read_final_loop_child_approval_preflight_v1(p_shift_id)->'plans') p(value)\n    WHERE p.value->>'plan_id'=v_plan.plan_id::text\n     AND p.value->>'independent_goal_acceptance_verified'='true'\n     AND p.value->>'owner_approval_claim_window_current'='true') THEN\n  RETURN pg_catalog.jsonb_build_object('status','FINAL_LOOP_OWNER_ACCEPTANCE_SCOPE_NOT_CURRENT',\n   'child_claimed',false,'original_job_completed',false);END IF;\n IF pg_catalog.jsonb_array_length(v_plan.source_plan->'bounded_scopes')\n    <>v_plan.proposed_scope_count THEN\n  RETURN pg_catalog.jsonb_build_object('status','FINAL_LOOP_SOURCE_SCOPES_CHANGED',\n   'child_claimed',false,'original_job_completed',false);END IF;\n IF v_packet.state='APPROVED_ONCE' THEN\n  FOR v_scope IN SELECT value FROM pg_catalog.jsonb_array_elements(\n   v_plan.source_plan->'bounded_scopes') item(value) LOOP\n   v_work:='work:'||pg_catalog.left(pg_catalog.encode(pg_catalog.sha256(\n    pg_catalog.convert_to('reality:final-loop-child-v1:'||\n     v_packet.packet_id::text||':'||(v_scope->>'index')||':'||\n     (v_scope->>'proposed_scope_sha256'),'UTF8')),'hex'),32);\n   INSERT INTO reality_internal.final_loop_child_review_work_v1\n    (child_work_id,packet_id,plan_id,owner_id,shift_id,\n     parent_original_work_id,scope_index,scope_sha256,\n     source_manifest_sha256,source_head_sha,acceptance_contract_sha256)\n   VALUES(v_work,v_packet.packet_id,v_plan.plan_id,v_packet.owner_id,\n    v_packet.shift_id,v_packet.parent_original_work_id,\n    (v_scope->>'index')::integer,v_scope->>'proposed_scope_sha256',\n    v_plan.source_manifest_sha256,v_plan.source_head_sha,\n    v_packet.acceptance_contract_sha256)\n   ON CONFLICT DO NOTHING;\n  END LOOP;\n  UPDATE reality_internal.final_loop_child_approval_packets_v1\n   SET state='EFFECT_RESERVED_RECONCILE_ONLY'\n   WHERE packet_id=v_packet.packet_id AND state='APPROVED_ONCE';\n END IF;\n SELECT count(*) INTO v_actual FROM\n  reality_internal.final_loop_child_review_work_v1 c\n WHERE c.packet_id=v_packet.packet_id AND c.plan_id=v_plan.plan_id\n  AND c.shift_id=v_packet.shift_id\n  AND c.parent_original_work_id=v_packet.parent_original_work_id\n  AND c.source_manifest_sha256=v_plan.source_manifest_sha256;\n IF v_actual<>v_plan.proposed_scope_count THEN\n  RAISE EXCEPTION 'FINAL_LOOP_CHILD_ATOMIC_SCOPE_ADMISSION_INCOMPLETE';END IF;\n SELECT c.* INTO v_child FROM\n  reality_internal.final_loop_child_review_work_v1 c\n WHERE c.packet_id=v_packet.packet_id AND c.phase='ADMITTED'\n ORDER BY c.scope_index LIMIT 1 FOR UPDATE SKIP LOCKED;\n IF NOT FOUND THEN\n  RETURN pg_catalog.jsonb_build_object(\n   'status','FINAL_LOOP_ALL_CHILDREN_CLAIMED_OR_PENDING_VERIFICATION',\n   'parent_original_work_id',v_packet.parent_original_work_id,\n   'child_claimed',false,'original_job_completed',false);END IF;\n UPDATE reality_internal.final_loop_child_review_work_v1\n SET phase='CLAIMED',claimant_worker_run_id=p_worker_run_id,\n  claimed_at=pg_catalog.clock_timestamp(),\n  claim_id=pg_catalog.gen_random_uuid(),\n  updated_at=pg_catalog.clock_timestamp()\n WHERE child_work_id=v_child.child_work_id AND phase='ADMITTED'\n RETURNING * INTO v_child;\n IF NOT FOUND THEN\n  RETURN pg_catalog.jsonb_build_object(\n   'status','FINAL_LOOP_CHILD_CONCURRENT_CLAIM_NOT_COMMITTED',\n   'child_claimed',false,'original_job_completed',false);END IF;\n SELECT value INTO v_scope FROM pg_catalog.jsonb_array_elements(\n  v_plan.source_plan->'bounded_scopes') item(value)\n WHERE (item.value->>'index')::integer=v_child.scope_index;\n RETURN pg_catalog.jsonb_build_object(\n  'status','FINAL_LOOP_EXACT_SIGNED_CHILD_CLAIMED_ONCE',\n  'owner_id',v_child.owner_id,'shift_id',v_child.shift_id,\n  'child_work_id',v_child.child_work_id,'claim_id',v_child.claim_id,\n  'claimant_worker_run_id',v_child.claimant_worker_run_id,\n  'parent_original_work_id',v_child.parent_original_work_id,\n  'source_ref',v_plan.source_ref,'source_head_sha',v_child.source_head_sha,\n  'source_manifest_sha256',v_child.source_manifest_sha256,\n  'source_proof_sha256',v_plan.source_proof_sha256,\n  'acceptance_contract_sha256',v_child.acceptance_contract_sha256,\n  'approval_receipt_sha256',v_packet.owner_approval_receipt_sha256,\n  'scope_index',v_child.scope_index,'scope_sha256',v_child.scope_sha256,\n  'scope',v_scope,\n  'phase',v_child.phase,'child_claimed',true,'model_invoked',false,\n  'external_effect_performed',false,'original_job_completed',false,\n  'parent_obligation_remains_open',true,'production_changed',false);\nEND $function$;\nCREATE OR REPLACE FUNCTION public.reality_read_final_loop_child_model_scope_v1(p_child_work_id text, p_claim_id uuid, p_worker_run_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE v_child record;v_plan record;v_packet record;\nBEGIN\n IF current_user<>'service_role' THEN\n  RAISE EXCEPTION 'FINAL_LOOP_CHILD_MODEL_SCOPE_SERVICE_ONLY';END IF;\n SELECT c.* INTO v_child FROM\n  reality_internal.final_loop_child_review_work_v1 c\n WHERE c.child_work_id=p_child_work_id AND c.claim_id=p_claim_id\n  AND c.claimant_worker_run_id=p_worker_run_id AND c.phase='CLAIMED';\n IF NOT FOUND THEN\n  RETURN pg_catalog.jsonb_build_object(\n   'status','FINAL_LOOP_CHILD_MODEL_CURRENT_CLAIM_NOT_FOUND',\n   'model_authorized',false);END IF;\n SELECT * INTO v_plan FROM reality_internal.final_loop_pr_source_plans_v1\n  WHERE plan_id=v_child.plan_id;\n SELECT * INTO v_packet FROM reality_internal.final_loop_child_approval_packets_v1\n  WHERE packet_id=v_child.packet_id;\n IF v_packet.state<>'EFFECT_RESERVED_RECONCILE_ONLY'\n  OR v_packet.owner_approval_receipt_sha256 IS NULL\n  OR v_packet.acceptance_contract_sha256<>v_child.acceptance_contract_sha256\n  OR v_plan.source_manifest_sha256<>v_child.source_manifest_sha256\n  OR NOT EXISTS(SELECT 1 FROM reality_internal.signed_worker_actual_runs_v1 r\n   WHERE r.run_id=p_worker_run_id AND r.status='STARTED'\n    AND r.finished_at IS NULL)\n  OR NOT EXISTS(SELECT 1 FROM reality_internal.governed_employee_shifts_v1 s\n   WHERE s.shift_id=v_child.shift_id AND s.owner_id=v_child.owner_id\n    AND s.closed_at IS NULL AND s.authorized_at IS NOT NULL\n    AND s.planned_end_at='infinity'::timestamptz)\n THEN RETURN pg_catalog.jsonb_build_object(\n  'status','FINAL_LOOP_CHILD_MODEL_AUTHORITY_OR_SOURCE_STALE',\n  'model_authorized',false);END IF;\n RETURN pg_catalog.jsonb_build_object(\n  'status','FINAL_LOOP_CHILD_CURRENT_SIGNED_MODEL_READBACK',\n  'owner_id',v_child.owner_id,'shift_id',v_child.shift_id,\n  'child_work_id',v_child.child_work_id,\n  'claim_id',v_child.claim_id,\n  'worker_run_id',p_worker_run_id,\n  'parent_original_work_id',v_child.parent_original_work_id,\n  'source_ref',v_plan.source_ref,'source_head_sha',v_child.source_head_sha,\n  'source_manifest_sha256',v_child.source_manifest_sha256,\n  'acceptance_contract_sha256',v_child.acceptance_contract_sha256,\n  'scope_sha256',v_child.scope_sha256,\n  'phase',v_child.phase,'model_response_id',v_child.model_response_id,\n  'read_only_model_execution',true,'model_authorized',true,\n  'external_effect_authorized',false,\n  'original_job_completed',false,'production_changed',false);\nEND $function$;\nCREATE OR REPLACE FUNCTION public.reality_read_final_loop_child_model_scope_v1(p_child_work_id text, p_claim_id uuid, p_worker_run_id uuid, p_canonical_handoff jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE a jsonb;\nBEGIN\n a:=reality_internal.check_final_loop_canonical_child_scope_v1(\n  (p_canonical_handoff->>'shift_id')::uuid,p_worker_run_id,p_canonical_handoff);\n IF a->>'status' IS DISTINCT FROM 'FINAL_LOOP_CANONICAL_CHILD_SCOPE_CURRENT' THEN RETURN a;END IF;\n IF NOT reality_internal.final_loop_canonical_child_matches_v1(p_child_work_id,p_canonical_handoff)\n THEN RETURN pg_catalog.jsonb_build_object('status','FINAL_LOOP_CANONICAL_MODEL_ORIGINAL_SCOPE_DRIFT','model_authorized',false);END IF;\n RETURN public.reality_read_final_loop_child_model_scope_v1(p_child_work_id,p_claim_id,p_worker_run_id);\nEND $function$;\nCREATE OR REPLACE FUNCTION public.reality_read_final_loop_child_verify_v1(p_shift_id uuid, p_verifier_run_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE v_child record;v_plan record;v_scope jsonb;\nBEGIN\n IF current_user<>'service_role' THEN\n  RAISE EXCEPTION 'FINAL_LOOP_CHILD_VERIFY_SERVICE_ONLY'; END IF;\n IF p_shift_id IS NULL OR p_verifier_run_id IS NULL OR\n  NOT EXISTS(SELECT 1 FROM reality_internal.signed_worker_actual_runs_v1 r\n   WHERE r.run_id=p_verifier_run_id AND r.status='STARTED'\n    AND r.finished_at IS NULL\n    AND r.started_at>=pg_catalog.clock_timestamp()-interval '10 minutes') THEN\n  RETURN pg_catalog.jsonb_build_object(\n   'status','FINAL_LOOP_CHILD_INDEPENDENT_SIGNED_RUN_REQUIRED',\n   'verification_committed',false);END IF;\n SELECT c.* INTO v_child FROM\n reality_internal.final_loop_child_review_work_v1 c\n JOIN reality_internal.final_loop_child_approval_packets_v1 p\n  ON p.packet_id=c.packet_id\n WHERE c.shift_id=p_shift_id AND c.phase='PREPARED'\n  AND c.claimant_worker_run_id<>p_verifier_run_id\n  AND c.model_response_id ~ '^resp_[A-Za-z0-9_-]{4,160}$'\n  AND c.review_sha256 ~ '^sha256:[a-f0-9]{64}$'\n  AND p.state='EFFECT_RESERVED_RECONCILE_ONLY'\n  AND EXISTS(SELECT 1 FROM reality_internal.governed_employee_shifts_v1 s\n   WHERE s.shift_id=c.shift_id AND s.owner_id=c.owner_id\n    AND s.closed_at IS NULL AND s.planned_end_at='infinity'::timestamptz)\n ORDER BY c.updated_at,c.scope_index LIMIT 1;\n IF NOT FOUND THEN RETURN pg_catalog.jsonb_build_object(\n  'status','FINAL_LOOP_NO_PREPARED_CHILD_FOR_INDEPENDENT_VERIFICATION',\n  'verification_committed',false);END IF;\n SELECT * INTO v_plan FROM reality_internal.final_loop_pr_source_plans_v1\n WHERE plan_id=v_child.plan_id;\n SELECT value INTO v_scope FROM pg_catalog.jsonb_array_elements(\n  v_plan.source_plan->'bounded_scopes') item(value)\n WHERE (item.value->>'index')::integer=v_child.scope_index;\n RETURN pg_catalog.jsonb_build_object(\n  'status','FINAL_LOOP_INDEPENDENT_CHILD_VERIFICATION_CANDIDATE',\n  'owner_id',v_child.owner_id,'shift_id',v_child.shift_id,\n  'child_work_id',v_child.child_work_id,\n  'parent_original_work_id',v_child.parent_original_work_id,\n  'source_ref',v_plan.source_ref,'source_head_sha',v_child.source_head_sha,\n  'source_manifest_sha256',v_child.source_manifest_sha256,\n  'source_proof_sha256',v_plan.source_proof_sha256,\n  'acceptance_contract_sha256',v_child.acceptance_contract_sha256,\n  'scope_index',v_child.scope_index,'scope_sha256',v_child.scope_sha256,\n  'scope',v_scope,'model_response_id',v_child.model_response_id,\n  'review_body',v_child.review_body,'review_sha256',v_child.review_sha256,\n  'original_generation_worker_run_id',v_child.claimant_worker_run_id,\n  'independent_verifier_run_id',p_verifier_run_id,\n  'read_only',true,'verification_committed',false,\n  'original_job_completed',false,'production_changed',false);\nEND $function$;\nCREATE OR REPLACE FUNCTION public.reality_read_final_loop_child_verify_v1(p_shift_id uuid, p_verifier_run_id uuid, p_canonical_handoff jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE a jsonb; v jsonb;\nBEGIN\n a:=reality_internal.check_final_loop_canonical_child_scope_v1(p_shift_id,p_verifier_run_id,p_canonical_handoff);\n IF a->>'status' IS DISTINCT FROM 'FINAL_LOOP_CANONICAL_CHILD_SCOPE_CURRENT' THEN RETURN a;END IF;\n v:=public.reality_read_final_loop_child_verify_v1(p_shift_id,p_verifier_run_id);\n IF v->>'status'='FINAL_LOOP_INDEPENDENT_CHILD_VERIFICATION_CANDIDATE'\n  AND NOT reality_internal.final_loop_canonical_child_matches_v1(v->>'child_work_id',p_canonical_handoff)\n THEN RETURN pg_catalog.jsonb_build_object('status','FINAL_LOOP_CANONICAL_VERIFIER_ORIGINAL_SCOPE_DRIFT',\n  'original_job_completed',false,'production_changed',false);END IF;\n RETURN v;\nEND $function$;\nCREATE OR REPLACE FUNCTION public.reality_prepare_final_loop_child_review_v1(p_child_work_id text, p_claim_id uuid, p_worker_run_id uuid, p_head_sha text, p_model_response_id text, p_review_body text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE v_child record;v_hash text;v_scope jsonb;v_plan record;\nBEGIN\n IF current_user<>'service_role' THEN\n  RAISE EXCEPTION 'FINAL_LOOP_CHILD_PREPARE_SERVICE_ONLY';END IF;\n IF p_child_work_id !~ '^work:[a-f0-9]{32}$'\n  OR p_claim_id IS NULL OR p_worker_run_id IS NULL\n  OR coalesce(p_head_sha,'') !~ '^[a-f0-9]{40}$'\n  OR coalesce(p_model_response_id,'') !~ '^resp_[A-Za-z0-9_-]{4,160}$'\n  OR pg_catalog.length(coalesce(p_review_body,'')) NOT BETWEEN 100 AND 4000\n THEN RETURN pg_catalog.jsonb_build_object(\n  'status','FINAL_LOOP_CHILD_PREPARE_INVALID_SCOPE',\n  'review_prepared',false,'original_job_completed',false);END IF;\n SELECT c.* INTO v_child\n FROM reality_internal.final_loop_child_review_work_v1 c\n WHERE c.child_work_id=p_child_work_id AND c.claim_id=p_claim_id\n  AND c.claimant_worker_run_id=p_worker_run_id AND c.phase='CLAIMED'\n  AND c.source_head_sha=p_head_sha FOR UPDATE;\n IF NOT FOUND THEN RETURN pg_catalog.jsonb_build_object(\n  'status','FINAL_LOOP_CHILD_ORIGINAL_CLAIM_OR_SOURCE_CHANGED',\n  'review_prepared',false,'original_job_completed',false);END IF;\n SELECT * INTO v_plan FROM reality_internal.final_loop_pr_source_plans_v1\n WHERE plan_id=v_child.plan_id;\n SELECT value INTO v_scope FROM pg_catalog.jsonb_array_elements(\n  v_plan.source_plan->'bounded_scopes') item(value)\n WHERE (item.value->>'index')::integer=v_child.scope_index;\n IF v_scope->>'proposed_scope_sha256'<>v_child.scope_sha256 OR\n  NOT EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(\n   v_scope->'files') item(value)\n   WHERE p_review_body LIKE '%'||(item.value->>'path')||'%') OR\n  NOT EXISTS(SELECT 1 FROM reality_internal.signed_worker_actual_runs_v1 r\n   WHERE r.run_id=p_worker_run_id AND r.status='STARTED'\n    AND r.finished_at IS NULL)\n THEN RETURN pg_catalog.jsonb_build_object(\n  'status','FINAL_LOOP_CHILD_PREPARED_PATCH_OR_WORKER_NOT_VERIFIED',\n  'review_prepared',false,'original_job_completed',false);END IF;\n v_hash:='sha256:'||pg_catalog.encode(pg_catalog.sha256(\n  pg_catalog.convert_to(p_review_body,'UTF8')),'hex');\n UPDATE reality_internal.final_loop_child_review_work_v1\n SET phase='PREPARED',model_response_id=p_model_response_id,\n  review_body=p_review_body,review_sha256=v_hash,\n  updated_at=pg_catalog.clock_timestamp()\n WHERE child_work_id=p_child_work_id AND phase='CLAIMED';\n RETURN pg_catalog.jsonb_build_object(\n  'status','FINAL_LOOP_CHILD_MODEL_ARTIFACT_PREPARED_NOT_VERIFIED',\n  'child_work_id',p_child_work_id,'parent_original_work_id',\n   v_child.parent_original_work_id,\n  'review_sha256',v_hash,'source_head_sha',v_child.source_head_sha,\n  'review_prepared',true,'independent_verification_required',true,\n  'original_job_completed',false,'production_changed',false);\nEND $function$;\nCREATE OR REPLACE FUNCTION public.reality_prepare_final_loop_child_review_v1(p_child_work_id text, p_claim_id uuid, p_worker_run_id uuid, p_head_sha text, p_model_response_id text, p_review_body text, p_canonical_handoff jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE a jsonb; v jsonb;\nBEGIN\n a:=public.reality_read_final_loop_child_model_scope_v1(\n  p_child_work_id,p_claim_id,p_worker_run_id,p_canonical_handoff);\n IF a->>'status' IS DISTINCT FROM 'FINAL_LOOP_CHILD_CURRENT_SIGNED_MODEL_READBACK'\n  OR a->>'model_authorized' IS DISTINCT FROM 'true'\n THEN RETURN pg_catalog.jsonb_build_object('status','FINAL_LOOP_CANONICAL_PREPARE_CONTINUITY_DRIFT_NO_REPLAY',\n  'original_job_completed',false,'production_changed',false);END IF;\n v:=public.reality_prepare_final_loop_child_review_v1(p_child_work_id,p_claim_id,p_worker_run_id,\n  p_head_sha,p_model_response_id,p_review_body);\n RETURN v;\nEND $function$;\nCREATE OR REPLACE FUNCTION public.reality_record_final_loop_child_verified_v1(p_child_work_id text, p_verifier_run_id uuid, p_review_sha256 text, p_source_head_sha text, p_source_manifest_sha256 text, p_evidence jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE v_child record;v_plan record;v_scope jsonb;v_path jsonb;\n v_count integer;v_distinct integer;v_receipt text;v_review text;\nBEGIN\n IF current_user<>'service_role' THEN\n  RAISE EXCEPTION 'FINAL_LOOP_CHILD_VERIFICATION_SERVICE_ONLY';END IF;\n IF p_verifier_run_id IS NULL OR\n  coalesce(p_child_work_id,'') !~ '^work:[a-f0-9]{32}$' OR\n  coalesce(p_review_sha256,'') !~ '^sha256:[a-f0-9]{64}$' OR\n  coalesce(p_source_head_sha,'') !~ '^[a-f0-9]{40}$' OR\n  coalesce(p_source_manifest_sha256,'') !~ '^sha256:[a-f0-9]{64}$' OR\n  pg_catalog.jsonb_typeof(p_evidence)<>'object' OR\n  p_evidence->>'schema'<>'reality-final-loop-independent-patch-review-v1' OR\n  p_evidence->>'review_source_verified'<>'true' OR\n  p_evidence->>'all_scope_patches_checked'<>'true' OR\n  p_evidence->>'independent_model_used'<>'true' OR\n  p_evidence->>'read_only'<>'true' OR\n  p_evidence->>'production_changed'<>'false' OR\n  p_evidence->>'source_manifest_sha256'<>p_source_manifest_sha256 OR\n  p_evidence->>'source_head_sha'<>p_source_head_sha OR\n  p_evidence->>'review_sha256'<>p_review_sha256 OR\n  coalesce(p_evidence->>'verifier_model_response_id','')\n   !~ '^resp_[A-Za-z0-9_-]{4,160}$' OR\n  coalesce(p_evidence->>'provider_evidence_sha256','')\n   !~ '^sha256:[a-f0-9]{64}$' OR\n  coalesce(p_evidence->>'verifier_verdict_sha256','')\n   !~ '^sha256:[a-f0-9]{64}$' OR\n  pg_catalog.jsonb_typeof(p_evidence->'verified_paths')<>'array'\n THEN RETURN pg_catalog.jsonb_build_object(\n  'status','FINAL_LOOP_INDEPENDENT_CHILD_PROOF_INVALID',\n  'independently_verified',false,'original_job_completed',false);END IF;\n SELECT c.* INTO v_child FROM\n  reality_internal.final_loop_child_review_work_v1 c\n WHERE c.child_work_id=p_child_work_id AND c.phase='PREPARED'\n  AND c.claimant_worker_run_id<>p_verifier_run_id\n  AND c.review_sha256=p_review_sha256\n  AND c.source_head_sha=p_source_head_sha\n  AND c.source_manifest_sha256=p_source_manifest_sha256\n FOR UPDATE;\n IF NOT FOUND OR NOT EXISTS(\n  SELECT 1 FROM reality_internal.signed_worker_actual_runs_v1 r\n  WHERE r.run_id=p_verifier_run_id AND r.status='STARTED'\n   AND r.finished_at IS NULL\n   AND r.started_at>=pg_catalog.clock_timestamp()-interval '10 minutes')\n THEN RETURN pg_catalog.jsonb_build_object(\n  'status','FINAL_LOOP_CHILD_VERIFIER_RUN_OR_CLAIM_UNVERIFIED',\n  'independently_verified',false,'original_job_completed',false);END IF;\n SELECT * INTO v_plan FROM reality_internal.final_loop_pr_source_plans_v1 p\n WHERE p.plan_id=v_child.plan_id AND p.shift_id=v_child.shift_id\n  AND p.source_manifest_sha256=v_child.source_manifest_sha256;\n SELECT value INTO v_scope FROM pg_catalog.jsonb_array_elements(\n  v_plan.source_plan->'bounded_scopes') item(value)\n WHERE (item.value->>'index')::integer=v_child.scope_index;\n IF v_scope->>'proposed_scope_sha256'<>v_child.scope_sha256\n  OR p_evidence->>'child_work_id'<>v_child.child_work_id\n  OR p_evidence->>'parent_original_work_id'<>v_child.parent_original_work_id\n  OR p_evidence->>'scope_sha256'<>v_child.scope_sha256\n  OR p_evidence->>'independent_verifier_run_id'<>p_verifier_run_id::text\n  OR (p_evidence->>'verifier_model_response_id')=v_child.model_response_id\n  OR p_evidence->>'review_source_verified'<>'true'\n  OR pg_catalog.jsonb_array_length(p_evidence->'verified_paths')\n     <>(v_scope->>'file_count')::integer THEN\n   RETURN pg_catalog.jsonb_build_object(\n    'status','FINAL_LOOP_CHILD_INDEPENDENT_SCOPE_COVERAGE_MISMATCH',\n    'independently_verified',false,'original_job_completed',false);\n END IF;\n -- Full, unique, EXACT scope inventory. A model verdict by itself cannot\n -- replace the independent provider patch recheck done by the worker.\n SELECT count(DISTINCT x.value#>>'{}') INTO v_distinct\n FROM pg_catalog.jsonb_array_elements(\n  p_evidence->'verified_paths') x(value);\n IF v_distinct<>(v_scope->>'file_count')::integer OR EXISTS(\n  SELECT 1 FROM pg_catalog.jsonb_array_elements(\n   p_evidence->'verified_paths') x(value)\n  WHERE pg_catalog.jsonb_typeof(x.value)<>'string'\n   OR NOT EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(\n     v_scope->'files') f(value)\n     WHERE f.value->>'path'=x.value#>>'{}')) THEN\n  RETURN pg_catalog.jsonb_build_object(\n   'status','FINAL_LOOP_CHILD_INDEPENDENT_PATHS_MISSING',\n   'independently_verified',false,'original_job_completed',false);\n END IF;\n v_review:='sha256:'||pg_catalog.encode(\n  pg_catalog.sha256(pg_catalog.convert_to(v_child.review_body,'UTF8')),'hex');\n IF v_review<>p_review_sha256 THEN\n  RETURN pg_catalog.jsonb_build_object(\n   'status','FINAL_LOOP_CHILD_PREPARED_REVIEW_DIGEST_MISMATCH',\n   'independently_verified',false,'original_job_completed',false); END IF;\n v_receipt:='sha256:'||pg_catalog.encode(\n  pg_catalog.sha256(pg_catalog.convert_to((pg_catalog.jsonb_build_object(\n    'child_work_id',v_child.child_work_id,\n    'parent_original_work_id',v_child.parent_original_work_id,\n    'review_sha256',v_child.review_sha256,\n    'source_manifest_sha256',v_child.source_manifest_sha256,\n    'independent_verifier_run_id',p_verifier_run_id,\n    'provider_evidence_sha256',p_evidence->>'provider_evidence_sha256',\n    'verifier_verdict_sha256',p_evidence->>'verifier_verdict_sha256'\n  ) || CASE WHEN p_evidence ? 'canonical_continuity_root_id' THEN\n   pg_catalog.jsonb_build_object(\n    'canonical_continuity_root_id',p_evidence->'canonical_continuity_root_id',\n    'canonical_continuity_head_sha256',p_evidence->'canonical_continuity_head_sha256',\n    'canonical_continuity_revision',p_evidence->'canonical_continuity_revision',\n    'canonical_owner_approval_receipt_sha256',p_evidence->'canonical_owner_approval_receipt_sha256')\n   ELSE '{}'::jsonb END)::text,'UTF8')),'hex');\n UPDATE reality_internal.final_loop_child_review_work_v1 SET\n  phase='INDEPENDENTLY_VERIFIED',\n  independent_verifier_run_id=p_verifier_run_id,\n  independent_provider_evidence_sha256=\n   p_evidence->>'provider_evidence_sha256',\n  independent_review_receipt_sha256=v_receipt,\n  verifier_evidence=p_evidence,\n  verified_at=pg_catalog.clock_timestamp(),\n  updated_at=pg_catalog.clock_timestamp()\n WHERE child_work_id=v_child.child_work_id AND phase='PREPARED';\n RETURN pg_catalog.jsonb_build_object(\n  'status','FINAL_LOOP_CHILD_REVIEW_INDEPENDENTLY_VERIFIED_PARENT_OPEN',\n  'child_work_id',v_child.child_work_id,\n  'parent_original_work_id',v_child.parent_original_work_id,\n  'independent_receipt_sha256',v_receipt,\n  'independently_verified',true,'parent_obligation_remains_open',true,\n  'original_job_completed',false,'production_changed',false);\nEND $function$;\nCREATE OR REPLACE FUNCTION public.reality_record_final_loop_child_verified_v1(p_child_work_id text, p_verifier_run_id uuid, p_review_sha256 text, p_source_head_sha text, p_source_manifest_sha256 text, p_evidence jsonb, p_canonical_handoff jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE a jsonb; v jsonb; e jsonb;\nBEGIN\n a:=public.reality_read_final_loop_child_verify_v1(\n  (p_canonical_handoff->>'shift_id')::uuid,p_verifier_run_id,p_canonical_handoff);\n IF a->>'status' IS DISTINCT FROM 'FINAL_LOOP_INDEPENDENT_CHILD_VERIFICATION_CANDIDATE'\n  OR a->>'child_work_id' IS DISTINCT FROM p_child_work_id\n  OR a->>'review_sha256' IS DISTINCT FROM p_review_sha256\n THEN RETURN pg_catalog.jsonb_build_object('status','FINAL_LOOP_CANONICAL_VERIFIER_CONTINUITY_DRIFT_NO_REPLAY',\n  'original_job_completed',false,'production_changed',false);END IF;\n -- The trusted canonical service, not the isolated model, stamps lineage\n -- into the existing verifier evidence field. No independent outcome is\n -- implied for the original until its own settlement/Universe return.\n e:=p_evidence||pg_catalog.jsonb_build_object(\n  'canonical_continuity_root_id',p_canonical_handoff->'continuity_root_id',\n  'canonical_continuity_head_sha256',p_canonical_handoff->'continuity_head_sha256',\n  'canonical_continuity_revision',p_canonical_handoff->'revision',\n  'canonical_owner_approval_receipt_sha256',p_canonical_handoff->'owner_approval_receipt_sha256');\n v:=public.reality_record_final_loop_child_verified_v1(p_child_work_id,p_verifier_run_id,\n  p_review_sha256,p_source_head_sha,p_source_manifest_sha256,e);\n RETURN v;\nEND $function$;\nALTER TABLE reality_internal.final_loop_resume_events_v1\n ADD COLUMN event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ADD COLUMN owner_id uuid,ADD COLUMN original_work_id text,\n ADD COLUMN source_ref text,ADD COLUMN signal_kind text,ADD COLUMN source_receipt_sha256 text,ADD COLUMN previous_receipt_sha256 text,\n ADD COLUMN event_causality_sha256 text,ADD COLUMN continuity_head_sha256 text,ADD COLUMN continuity_revision bigint,\n ADD COLUMN signal_next_action text,ADD COLUMN release_continuation_claim_id uuid,ADD COLUMN ledger_return_condition_sha256 text,\n ADD COLUMN governed_wake_worker_run_id uuid,ADD COLUMN governed_wake_request_id bigint,ADD COLUMN governed_wake_nonce uuid,\n ADD COLUMN governed_wake_requested_at timestamptz,ADD COLUMN governed_wake_queued_at timestamptz;\nALTER TABLE reality_internal.signed_worker_actual_runs_v1 ADD COLUMN worker_stage text;\nCREATE TABLE reality_internal.governed_worker_release_approvals_v1(request_id uuid PRIMARY KEY,claim_id uuid UNIQUE,owner_id uuid,shift_id uuid,\n state text,capability_key text,approval_receipt_sha256 text,provider_alias_observed_at timestamptz,claimed_at timestamptz,\n provider_alias_observed_deployment_id text,runtime_scope jsonb,release_sha text,release_ref text);\nCREATE TABLE reality_internal.governed_signed_worker_release_wakes_v1(worker_run_id uuid,release_claim_id uuid,\n running_release_sha text,running_release_ref text,owner_id uuid,shift_id uuid,operating_lane text,release_receipt_sha256 text);\nCREATE TABLE reality_internal.final_loop_resume_conditions_v1(shift_id uuid,owner_id uuid,original_work_id text,source_ref text,\n condition_kind text,state text,continuity_head_sha256 text,continuity_revision bigint,subscribed_receipt_sha256 text,updated_at timestamptz);\nCREATE TABLE reality_internal.final_loop_transition_receipts_v1(owner_id uuid,shift_id uuid,original_work_id text,source_ref text,\n continuity_root_id uuid,continuity_head_sha256 text,expected_revision bigint,worker_run_id uuid,decision text,reason_code text,receipt_sha256 text);\nCREATE TABLE public.universe_events(event_id uuid PRIMARY KEY,continuity_root_id uuid,worldline_id uuid,parent_event_id uuid,\n lineage_hash text,entity_type text,event_kind text,epistemic_status text,payload jsonb,evidence_refs jsonb,provenance jsonb,content_hash text);\nCREATE FUNCTION public.reality_continuity_canonical_json_v1(jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS 'SELECT $1::text';\nGRANT SELECT ON ALL TABLES IN SCHEMA reality_internal TO service_role;\nGRANT SELECT ON public.universe_events TO service_role;\n";
const scenario="\nDO $test$\nDECLARE o uuid:=gen_random_uuid();s uuid:=gen_random_uuid();p uuid:=gen_random_uuid();a uuid:=gen_random_uuid();\n root uuid:=gen_random_uuid(); t timestamptz:=clock_timestamp(); old_event uuid:=gen_random_uuid();\n w text:='work:'||repeat('a',32);src text:='https://github.com/fixture/review/pull/1'; head text:=repeat('b',40);\n mh text:='sha256:'||repeat('c',64);ac text:='sha256:'||repeat('d',64);ap text:='sha256:'||repeat('e',64);\n ch text:='sha256:'||repeat('f',64);budget jsonb; snap jsonb;qd text; guard jsonb;ob jsonb;scopes jsonb:='[]';obs jsonb:='[]';\n child text;sh text;run uuid;inv uuid; vr uuid; i integer;response jsonb;proposal jsonb;fp text; before_rows jsonb; new_run uuid:=gen_random_uuid(); new_verify_run uuid:=gen_random_uuid(); new_inv uuid:=gen_random_uuid(); new_verify_inv uuid:=gen_random_uuid(); old_inv uuid; old_claim uuid; request_id uuid:=gen_random_uuid(); prior_request uuid:=gen_random_uuid(); handoff jsonb; claim jsonb; candidate jsonb; approved jsonb; recorded jsonb; review text; proof jsonb; paths jsonb; rel uuid:=gen_random_uuid(); rel_request uuid:=gen_random_uuid(); rel_sha text:=repeat('8',40); base_event uuid:=gen_random_uuid(); ledger_event uuid:=gen_random_uuid(); receipt_event uuid:=gen_random_uuid(); ledger_run uuid:=gen_random_uuid(); wake uuid; ledger_wake uuid:=gen_random_uuid(); verifier_wake uuid:=gen_random_uuid(); chain jsonb; event_payload jsonb; prior_lineage text; current_lineage text; current_event uuid; child_receipt jsonb; obs_digest text; readback_guard jsonb; step int;\nBEGIN\n budget:=jsonb_build_object('original_work_id',w,'remaining_attempts',0,'new_attempt_authorized',false,'replay_permitted',false);\n snap:=jsonb_build_object('shift_id',s,'original_candidate_work_id',w,'recovery_terminal_history',budget);\n qd:='sha256:'||encode(sha256(convert_to(snap::text,'UTF8')),'hex');\n INSERT INTO reality_internal.governed_employee_shifts_v1(shift_id,owner_id,closed_at,authorized_at,planned_end_at,status,plan_fingerprint) VALUES(s,o,NULL,t,'infinity','RUNNING',ac);\n INSERT INTO reality_internal.governed_employee_completion_warrants_v1 VALUES(s,o,ac,'ACTIVE','UNTIL_ALL_INDEPENDENT_INTERNAL_MAINTENANCE_RECEIPTS',jsonb_build_array(jsonb_build_object('source_ref',src)));\n INSERT INTO reality_internal.riley_pr_review_originals_v1(shift_id,owner_id,original_work_id,source_ref,phase) VALUES(s,o,w,src,'BLOCKED');\n INSERT INTO reality_internal.owner_continuity_qualification_routes_v1 VALUES(o,src,'SIGNED_SHIFT_SOURCE',snap,qd,t);\n FOR i IN 0..4 LOOP\n  child:='work:'||lpad(i::text,32,'0');sh:='sha256:'||lpad(i::text,64,'0');run:=gen_random_uuid();inv:=gen_random_uuid();\n  scopes:=scopes||jsonb_build_array(jsonb_build_object('index',i,'proposed_scope_sha256',sh,'file_count',CASE WHEN i=4 THEN 2 ELSE 8 END,'files',(SELECT jsonb_agg(jsonb_build_object('path','src/fixture-'||i||'-'||z||'.js')) FROM generate_series(1,CASE WHEN i=4 THEN 2 ELSE 8 END) z)));\n  INSERT INTO reality_internal.signed_worker_actual_runs_v1 VALUES(run,CASE WHEN i=3 THEN 'FAILED' ELSE 'COMPLETED' END,t-interval '1 minute',t);\n  IF i=4 THEN\n   vr:=gen_random_uuid();\n   INSERT INTO reality_internal.signed_worker_actual_runs_v1 VALUES(vr,'COMPLETED',t-interval '30 seconds',t);\n  ELSE vr:=NULL;END IF;\n  INSERT INTO reality_internal.final_loop_child_review_work_v1(child_work_id,plan_id,packet_id,owner_id,shift_id,parent_original_work_id,scope_index,scope_sha256,\n   source_manifest_sha256,source_head_sha,acceptance_contract_sha256,phase,claimant_worker_run_id,canonical_prepare_invocation_id,\n   canonical_verify_invocation_id,canonical_verify_invocation_run_id,independent_verifier_run_id,independent_review_receipt_sha256,\n   verifier_evidence,advisory_rejection_receipts,model_response_id,review_body,review_sha256)\n  VALUES(child,p,a,o,s,w,i,sh,mh,head,ac,CASE WHEN i=4 THEN 'INDEPENDENTLY_VERIFIED' ELSE 'CLAIMED' END,run,inv,\n   CASE WHEN i=4 THEN gen_random_uuid() ELSE NULL END,vr,vr,CASE WHEN i=4 THEN 'sha256:'||repeat('1',64) ELSE NULL END,\n   CASE WHEN i=4 THEN jsonb_build_object('canonical_continuity_root_id',root) ELSE NULL END,'{}',\n   CASE WHEN i=4 THEN 'resp_fixture' ELSE NULL END,CASE WHEN i=4 THEN 'prepared' ELSE NULL END,CASE WHEN i=4 THEN 'sha256:'||repeat('2',64) ELSE NULL END);\n  obs:=obs||jsonb_build_array(jsonb_build_object('child_work_id',child,'scope_sha256',sh,'invocation_id',inv,'worker_run_id',run,\n   'event_id',gen_random_uuid(),'release_sha',repeat('9',40),'worker_completed',i<>3,'model_artifact_recorded',i=4,\n   'provider_outcome_verified',false,'replay_authorized',false)||CASE WHEN i=3 THEN\n   jsonb_build_object('worker_terminal_status','FAILED','worker_failure_attested',true,'provider_outcome_unknown',true) ELSE '{}'::jsonb END);\n END LOOP;\n INSERT INTO reality_internal.final_loop_pr_source_plans_v1(plan_id,owner_id,shift_id,parent_original_work_id,source_ref,source_head_sha,source_manifest_sha256,source_plan,proposed_scope_count,file_count,source_proof_sha256,state) VALUES(p,o,s,w,src,head,mh,jsonb_build_object('bounded_scopes',scopes),5,34,ac,'PROPOSED_SOURCE_PLAN_AWAITING_INDEPENDENT_ADMISSION');\n INSERT INTO reality_internal.final_loop_child_approval_packets_v1(packet_id,plan_id,owner_id,shift_id,parent_original_work_id,source_ref,source_manifest_sha256,acceptance_contract_sha256,authority_effect,state,owner_approval_receipt_sha256,proposal_fingerprint,created_at,approved_at,owner_approval_request_id) VALUES(a,p,o,s,w,src,mh,ac,'READ_ONLY_INTERNAL_PR_REVIEW','EFFECT_RESERVED_RECONCILE_ONLY',ap,'sha256:'||repeat('3',64),t,t,prior_request);\n ob:=jsonb_build_object('original_work_id',w,'source_ref',src,'continuity_identity_verified',true,'qualifier_digest_verified',true,\n  'source_proof_verified',true,'independent_original_outcome_verified',false,'qualifier_receipt_sha256',qd,\n  'execution_spine_readback',jsonb_build_object('status','SIGNED_INVOCATION_OBSERVATIONS_RETURNED_ORIGINAL_OPEN','canonical_return_committed',true,\n  'replay_authorized',false,'provider_outcome_verified',false,'canonical_return_event_id',old_event,\n  'observation_sha256','sha256:'||encode(sha256(convert_to(obs::text,'UTF8')),'hex'),'observations',obs));\n guard:=jsonb_build_object('status','FINAL_LOOP_SHARED_CONTINUITY_CHECKED','owner_id',o,'shift_id',s,'continuity_root_id',root,\n  'continuity_head_sha256',ch,'revision',10,'no_new_executable_authority',true,'execution_authorized',false,'original_job_completed',false,\n  'production_changed',false,'worldline_parent_links_verified',true,'unverified_handoffs',0,'obligations',jsonb_build_array(ob));\n INSERT INTO public.recovery_fixture VALUES(s,guard);\n SELECT jsonb_agg(to_jsonb(c) ORDER BY c.scope_index) INTO before_rows FROM reality_internal.final_loop_child_review_work_v1 c WHERE c.shift_id=s;\n SET LOCAL ROLE service_role;\n response:=public.reality_read_final_loop_child_recovery_v1(s,p);\n RESET ROLE;\n proposal:=response->'recovery_qualification'->'proposal';fp:=response->'recovery_qualification'->>'proposal_sha256';\n IF response->>'provider_effect_uncertain' IS DISTINCT FROM 'true'\n  OR response->'recovery_qualification'->>'status' IS DISTINCT FROM 'SAME_ORIGINAL_MISSING_REVIEW_WORK_QUALIFIED_FOR_EXACT_OWNER_DECISION'\n  OR proposal->>'proposed_max_new_provider_calls' IS DISTINCT FROM '8'\n  OR proposal->>'preserved_verified_scope_count' IS DISTINCT FROM '1'\n  OR proposal->>'missing_scope_count' IS DISTINCT FROM '4'\n  OR proposal->>'continuity_revision' IS DISTINCT FROM '10'\n  OR proposal->>'new_budget_authorized' IS DISTINCT FROM 'false'\n  OR proposal->>'historical_invocation_replay_authorized' IS DISTINCT FROM 'false'\n  OR fp IS DISTINCT FROM ('sha256:'||encode(sha256(convert_to(proposal::text,'UTF8')),'hex'))\n  OR (SELECT count(*) FROM jsonb_array_elements(response->'children') x WHERE x->>'phase'='EFFECT_UNCERTAIN')<>4\n  OR response->'children'->4->>'phase' IS DISTINCT FROM 'VERIFIED'\n  OR response->'cross_scope'->>'independently_verified' IS DISTINCT FROM 'false'\n THEN RAISE EXCEPTION 'SAME_ORIGINAL_QUALIFICATION_FAILED %',response;END IF;\n SET LOCAL ROLE service_role;\n response:=public.reality_read_owner_final_loop_child_approvals_v1(o,s);\n RESET ROLE;\n IF response->'packets'->0->'recovery_qualification'->>'proposal_sha256' IS DISTINCT FROM fp\n THEN RAISE EXCEPTION 'OWNER_QUALIFICATION_NOT_CONNECTED';END IF;\n IF (SELECT jsonb_agg(to_jsonb(c) ORDER BY c.scope_index) FROM reality_internal.final_loop_child_review_work_v1 c WHERE c.shift_id=s) IS DISTINCT FROM before_rows\n THEN RAISE EXCEPTION 'READBACK_MUTATED_HISTORICAL_INVOCATION';END IF;\n\n -- Scope and signed run are synthetic fixture data. The actual canonical\n -- allocator, approval, transport fence and independent writer are exercised.\n handoff:=jsonb_build_object('plan_id',p,'packet_id',a,'owner_id',o,'shift_id',s,'parent_original_work_id',w,\n 'source_ref',src,'source_head_sha',head,'source_proof_sha256',ac,'source_manifest_sha256',mh,'acceptance_contract_sha256',ac,\n 'owner_approval_receipt_sha256',ap,'continuity_root_id',root,'continuity_head_sha256',ch,'revision',10,\n 'scope_fingerprints',(SELECT jsonb_agg(jsonb_build_object('index',x->'index','scope_sha256',x->>'proposed_scope_sha256')) FROM jsonb_array_elements(scopes) x));\n SELECT canonical_prepare_invocation_id,claim_id INTO old_inv,old_claim FROM reality_internal.final_loop_child_review_work_v1 WHERE plan_id=p AND scope_index=0;\n INSERT INTO reality_internal.signed_worker_actual_runs_v1 VALUES(new_run,'STARTED',t,NULL);\n SET LOCAL ROLE service_role;\n candidate:=reality_internal.read_final_loop_approved_recovery_candidate_v1(s,p);\n IF candidate IS NOT NULL THEN RAISE EXCEPTION 'UNAPPROVED_RECOVERY_CANDIDATE';END IF;\n approved:=public.reality_owner_approve_final_loop_child_v1(o,a,'sha256:'||repeat('7',64),mh,request_id);\n IF approved->>'approved' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'FORGED_APPROVAL_ACCEPTED';END IF;\n approved:=public.reality_owner_approve_final_loop_child_v1(o,a,fp,mh,request_id);\n IF approved->>'status' IS DISTINCT FROM 'FINAL_LOOP_SAME_OBLIGATION_RECOVERY_APPROVED_ONCE' THEN RAISE EXCEPTION 'EXACT_SYNTHETIC_APPROVAL_FAILED %',approved;END IF;\n candidate:=reality_internal.read_final_loop_approved_recovery_candidate_v1(s,p);\n IF candidate->>'historical_invocation_id' IS DISTINCT FROM old_inv::text THEN RAISE EXCEPTION 'APPROVED_CANDIDATE_MISSING %',candidate;END IF;\n\n RESET ROLE;\n -- The receipt from Chat uses the same packet, not a new original or warrant.\n SET LOCAL ROLE service_role;\n response:=public.reality_read_owner_final_loop_child_approvals_v1(o,s);\n IF response->'packets'->0->'recovery_approval'->>'approval_receipt_sha256' IS DISTINCT FROM approved->>'approval_receipt_sha256'\n THEN RAISE EXCEPTION 'CHAT_APPROVAL_RECEIPT_NOT_READ_BACK';END IF;\n RESET ROLE;\n INSERT INTO reality_internal.governed_worker_release_approvals_v1 VALUES(rel_request,rel,o,s,'CLAIMED_ONCE',\n  'VERIFY_EXISTING_APPROVED_CHILD_REVIEW_CLAIM','sha256:'||repeat('5',64),t,t,'fixture-deployment',\n  jsonb_build_object('target_deployment_id','fixture-deployment','target_environment','CANONICAL_BENCHMARK_PREVIEW',\n   'exact_runtime_database_contract_verified',true,'independent_gateway_ci_verified',true,'independent_qualification_branch_verified',true,\n   'independent_transport_proof_sha256','sha256:'||repeat('6',64),'child_execution_enabled',false,'parent_delivery_enabled',false,\n   'production_changed',false,'continuity_revision',10,'continuity_head_sha256',ch,'continuity_root_id',root,'original_work_id',w,\n   'source_ref',src,'qualifier_receipt_sha256',qd,'plan_fingerprint',ac),rel_sha,'fixture-release');\n INSERT INTO public.universe_events(event_id,continuity_root_id,worldline_id,lineage_hash) VALUES(base_event,root,root,substr(ch,8));\n UPDATE public.recovery_fixture f SET guard=jsonb_set(f.guard,'{obligations,0,next_qualified_action}',to_jsonb('VERIFY_EXISTING_APPROVED_CHILD_REVIEW_CLAIM'::text)) WHERE shift_id=s;\n INSERT INTO reality_internal.final_loop_resume_conditions_v1 VALUES(s,o,w,src,'QUALIFIER_PROOF_CHANGED','SUSPENDED',ch,10,qd,t);\n wake:=reality_internal.stage_final_loop_bounded_recovery_continuation_v1(rel_request);\n IF wake IS NULL OR reality_internal.stage_final_loop_bounded_recovery_continuation_v1(rel_request) IS NOT NULL\n THEN RAISE EXCEPTION 'INITIAL_APPROVED_EVENT_MISSING_OR_DUPLICATE';END IF;\n -- The fixture does not dispatch HTTP; record a synthetic observed event.\n UPDATE reality_internal.final_loop_resume_events_v1 SET state='SHADOW_OBSERVED' WHERE event_id=wake;\n SET LOCAL ROLE service_role;\n claim:=public.reality_claim_final_loop_child_review_v1(s,new_run,handoff);\n IF claim->>'status' IS DISTINCT FROM 'FINAL_LOOP_EXACT_SIGNED_CHILD_CLAIMED_ONCE'\n  OR claim->>'claim_id' IS NOT DISTINCT FROM old_claim::text\n  OR claim->'historical_prepare_fence'->>'invocation_id' IS DISTINCT FROM old_inv::text\n  OR claim->'same_obligation_continuation'->>'approval_receipt_sha256' IS DISTINCT FROM approved->>'approval_receipt_sha256'\n THEN RAISE EXCEPTION 'CANONICAL_CONTINUATION_CLAIM_FAILED %',claim;END IF;\n response:=public.reality_fence_final_loop_child_transport_v1(claim->>'child_work_id',(claim->>'claim_id')::uuid,new_run,'PREPARE',old_inv,true,handoff);\n IF response->>'status' IS DISTINCT FROM 'FINAL_LOOP_CHILD_HISTORICAL_INVOCATION_NO_REPLAY' THEN RAISE EXCEPTION 'HISTORICAL_REPLAY_ACCEPTED %',response;END IF;\n response:=public.reality_fence_final_loop_child_transport_v1(claim->>'child_work_id',(claim->>'claim_id')::uuid,new_run,'PREPARE',new_inv,true,handoff);\n IF response->>'status' IS DISTINCT FROM 'FINAL_LOOP_CHILD_CURRENT_SIGNED_MODEL_READBACK' THEN RAISE EXCEPTION 'DISTINCT_PREPARATION_FENCE_FAILED %',response;END IF;\n response:=public.reality_fence_final_loop_child_transport_v1(claim->>'child_work_id',(claim->>'claim_id')::uuid,new_run,'PREPARE',gen_random_uuid(),true,handoff);\n IF response->>'status' IS DISTINCT FROM 'FINAL_LOOP_CHILD_TRANSPORT_ALREADY_FENCED_NO_REPLAY' THEN RAISE EXCEPTION 'DUPLICATE_NEW_PREPARATION_ALLOWED %',response;END IF;\n RESET ROLE;\n SELECT string_agg(x->>'path'||' Finding: synthetic fixture review. Proposed test: fixture check.',E'\\n'),jsonb_agg(x->>'path')\n INTO review,paths FROM jsonb_array_elements(scopes->0->'files') x;\n SET LOCAL ROLE service_role;\n recorded:=public.reality_prepare_final_loop_child_review_v1(claim->>'child_work_id',(claim->>'claim_id')::uuid,new_run,head,'resp_fixture_new_prepare',review,handoff);\n IF recorded->>'status' IS DISTINCT FROM 'FINAL_LOOP_CHILD_MODEL_ARTIFACT_PREPARED_NOT_VERIFIED' THEN RAISE EXCEPTION 'PREPARATION_WRITER_FAILED %',recorded;END IF;\n RESET ROLE;\n UPDATE reality_internal.signed_worker_actual_runs_v1 SET status='COMPLETED',finished_at=clock_timestamp() WHERE run_id=new_run;\n INSERT INTO reality_internal.signed_worker_actual_runs_v1 VALUES(new_verify_run,'STARTED',clock_timestamp(),NULL);\n SET LOCAL ROLE service_role;\n response:=public.reality_fence_final_loop_child_transport_v1(claim->>'child_work_id',NULL,new_verify_run,'VERIFY',new_verify_inv,true,handoff);\n IF response->>'status' IS DISTINCT FROM 'FINAL_LOOP_INDEPENDENT_CHILD_VERIFICATION_CANDIDATE' THEN RAISE EXCEPTION 'DISTINCT_VERIFIER_FENCE_FAILED %',response;END IF;\n proof:=jsonb_build_object('schema','reality-final-loop-independent-patch-review-v1','child_work_id',claim->>'child_work_id',\n 'parent_original_work_id',w,'scope_sha256',claim->>'scope_sha256','source_manifest_sha256',mh,'source_head_sha',head,\n 'review_sha256',recorded->>'review_sha256','independent_verifier_run_id',new_verify_run,'verifier_model_response_id','resp_fixture_independent_verify',\n 'provider_evidence_sha256','sha256:'||repeat('5',64),'verifier_verdict_sha256','sha256:'||repeat('6',64),\n 'verified_paths',paths,'review_source_verified',true,'all_scope_patches_checked',true,'independent_model_used',true,'read_only',true,'production_changed',false);\n response:=public.reality_record_final_loop_child_verified_v1(claim->>'child_work_id',new_verify_run,recorded->>'review_sha256',head,mh,proof,handoff);\n IF response->>'status' IS DISTINCT FROM 'FINAL_LOOP_CHILD_REVIEW_INDEPENDENTLY_VERIFIED_PARENT_OPEN' THEN RAISE EXCEPTION 'EXISTING_INDEPENDENT_VERIFIER_FAILED %',response;END IF;\n response:=public.reality_read_final_loop_child_recovery_v1(s,p);\n IF response->'children'->0->>'phase' IS DISTINCT FROM 'VERIFIED'\n  OR response->'children'->0->'historical_prepare_fence'->>'invocation_id' IS DISTINCT FROM old_inv::text\n  OR response->'children'->0->>'canonical_prepare_invocation_id' IS DISTINCT FROM new_inv::text\n  OR response->'children'->0->>'canonical_verify_invocation_id' IS DISTINCT FROM new_verify_inv::text\n  OR response->>'historical_provider_outcome_uncertain' IS DISTINCT FROM 'true'\n  OR response->>'original_job_completed' IS DISTINCT FROM 'false'\n THEN RAISE EXCEPTION 'INDEPENDENT_READBACK_FAILED %',response;END IF;\n RESET ROLE;\n BEGIN\n  UPDATE reality_internal.final_loop_child_review_work_v1 SET historical_prepare_fence=NULL WHERE plan_id=p AND scope_index=0;\n  RAISE EXCEPTION 'HISTORY_MUTATION_NOT_REJECTED';\n EXCEPTION WHEN raise_exception THEN\n  IF SQLERRM<>'FINAL_LOOP_HISTORICAL_INVOCATION_OR_CONTINUATION_IMMUTABLE' THEN RAISE;END IF;\n END;\n IF (SELECT count(*) FROM reality_internal.final_loop_child_review_work_v1 WHERE plan_id=p)<>5\n OR (SELECT count(*) FROM reality_internal.final_loop_child_review_work_v1 WHERE plan_id=p AND phase='INDEPENDENTLY_VERIFIED')<>2\n OR (SELECT premodel_recovery_count FROM reality_internal.final_loop_child_review_work_v1 WHERE plan_id=p AND scope_index=0)<>1\n THEN RAISE EXCEPTION 'ORIGINAL_CHILD_OR_BUDGET_DRIFT';END IF;\n\n -- Create synthetic signed preparation-return and independent receipt\n -- observations representing two consecutive ledger commits. The real\n -- bounded lineage reader and existing broker staging are under test.\n UPDATE reality_internal.signed_worker_actual_runs_v1 SET status='COMPLETED',finished_at=clock_timestamp(),worker_stage='WORKER_RESPONSE_PUBLICATION' WHERE run_id=new_verify_run;\n INSERT INTO reality_internal.signed_worker_actual_runs_v1(run_id,status,started_at,finished_at,worker_stage)\n VALUES(ledger_run,'COMPLETED',t,t,'LEDGER_RETURN_RESPONSE_PUBLICATION');\n SELECT jsonb_build_object('child_work_id',c.child_work_id,'scope_sha256',c.scope_sha256,'prepare_invocation_id',c.canonical_prepare_invocation_id,\n 'verify_invocation_id',c.canonical_verify_invocation_id,'verifier_worker_run_id',new_verify_run,'release_claim_id',rel,\n 'independent_review_receipt_sha256',c.independent_review_receipt_sha256,'independently_verified',true,'prior_head_sha256','sha256:'||repeat('7',64),'prior_revision',11)\n INTO child_receipt FROM reality_internal.final_loop_child_review_work_v1 c WHERE c.plan_id=p AND c.scope_index=0;\n obs_digest:='sha256:'||encode(sha256(convert_to(obs::text,'UTF8')),'hex');\n prior_lineage:=substr(ch,8);current_lineage:=repeat('7',64);current_event:=base_event;\n FOR step IN 1..2 LOOP\n  event_payload:=jsonb_build_object('owner_id',o,'shift_id',s,'original_work_id',w,'source_ref',src,\n   'execution_authorized',false,'original_job_completed',false,'replay_authorized',false,'production_changed',false,\n   'terminal_recovery_history',budget,'observation_sha256',obs_digest,'invocation_observations',obs);\n  IF step=2 THEN event_payload:=event_payload||jsonb_build_object('independent_child_receipt',child_receipt);END IF;\n  INSERT INTO public.universe_events VALUES(CASE WHEN step=1 THEN ledger_event ELSE receipt_event END,root,root,current_event,current_lineage,\n   CASE WHEN step=1 THEN 'reality_final_loop_invocation_observation_v1' ELSE 'reality_final_loop_independent_child_receipt_observation_v1' END,\n   'OBSERVATION','OBSERVED',event_payload,jsonb_build_array(obs_digest),jsonb_build_object('worker_run_id',CASE WHEN step=1 THEN ledger_run ELSE new_verify_run END,\n    'continuity_spine',jsonb_build_object('prior_lineage_hash',prior_lineage,'source_event_id',current_event)),encode(sha256(convert_to(event_payload::text,'UTF8')),'hex'));\n  INSERT INTO reality_internal.final_loop_transition_receipts_v1 VALUES(o,s,w,src,root,'sha256:'||prior_lineage,9+step,\n   CASE WHEN step=1 THEN ledger_run ELSE new_verify_run END,'SUSPEND','PROVIDER_EFFECT_UNCERTAIN','sha256:'||repeat('5',64));\n  INSERT INTO reality_internal.governed_signed_worker_release_wakes_v1 VALUES(CASE WHEN step=1 THEN ledger_run ELSE new_verify_run END,rel,rel_sha,'fixture-release',o,s,'NORMAL_SIGNED_SHIFT','sha256:'||repeat('6',64));\n  INSERT INTO reality_internal.final_loop_resume_events_v1(event_id,shift_id,state,owner_id,original_work_id,source_ref,signal_kind,\n   source_receipt_sha256,continuity_head_sha256,continuity_revision,signal_next_action,release_continuation_claim_id,ledger_return_condition_sha256,\n   governed_wake_worker_run_id,governed_wake_request_id,governed_wake_nonce,governed_wake_requested_at,governed_wake_queued_at)\n  VALUES(CASE WHEN step=1 THEN ledger_wake ELSE verifier_wake END,s,'SHADOW_OBSERVED',o,w,src,'QUALIFIER_PROOF_CHANGED',qd,\n   'sha256:'||prior_lineage,9+step,'VERIFY_EXISTING_APPROVED_CHILD_REVIEW_CLAIM',rel,CASE WHEN step=1 THEN 'sha256:'||repeat('9',64) ELSE NULL END,\n   CASE WHEN step=1 THEN ledger_run ELSE new_verify_run END,step,gen_random_uuid(),t-interval '1 minute',t-interval '1 minute');\n  prior_lineage:=current_lineage;current_lineage:=repeat('9',64);current_event:=ledger_event;\n END LOOP;\n chain:=reality_internal.read_final_loop_bounded_release_chain_v1(rel,'sha256:'||repeat('9',64),12);\n IF chain->>'bounded_chain_steps' IS DISTINCT FROM '2' OR chain->>'last_entity_type' IS DISTINCT FROM 'reality_final_loop_independent_child_receipt_observation_v1'\n THEN RAISE EXCEPTION 'SUCCESSIVE_RELEASE_RECEIPT_CHAIN_UNVERIFIED %',chain;END IF;\n IF reality_internal.read_final_loop_bounded_release_chain_v1(rel,'sha256:'||repeat('0',64),12) IS NOT NULL\n  OR reality_internal.read_final_loop_bounded_release_chain_v1(rel,'sha256:'||repeat('9',64),19) IS NOT NULL\n THEN RAISE EXCEPTION 'FOREIGN_HEAD_OR_EXCESS_BUDGET_CHAIN_ACCEPTED';END IF;\n UPDATE public.recovery_fixture f SET guard=f.guard||jsonb_build_object('continuity_head_sha256','sha256:'||repeat('9',64),'revision',12) WHERE shift_id=s;\n UPDATE public.recovery_fixture f SET guard=jsonb_set(f.guard,'{obligations,0,independent_child_receipt_readback}',jsonb_build_array(jsonb_build_object('event_id',receipt_event,'receipt',child_receipt))) WHERE shift_id=s;\n UPDATE reality_internal.final_loop_resume_conditions_v1 SET continuity_head_sha256='sha256:'||repeat('9',64),continuity_revision=12,subscribed_receipt_sha256=qd WHERE shift_id=s;\n wake:=reality_internal.stage_final_loop_bounded_recovery_continuation_v1(rel_request);\n IF wake IS NULL OR reality_internal.stage_final_loop_bounded_recovery_continuation_v1(rel_request) IS NOT NULL\n  OR NOT EXISTS(SELECT 1 FROM reality_internal.final_loop_resume_events_v1 e WHERE e.event_id=wake AND e.continuity_revision=12\n   AND e.previous_receipt_sha256=child_receipt->>'independent_review_receipt_sha256' AND e.state='SHADOW_PENDING')\n THEN RAISE EXCEPTION 'NEXT_ORIGINAL_SCOPE_NOT_STAGED_EXACTLY_ONCE';END IF;\n -- A mutated receipt return invalidates the chain even after staging.\n UPDATE public.universe_events SET payload=payload||'{\"replay_authorized\":true}'::jsonb WHERE event_id=receipt_event;\n IF reality_internal.read_final_loop_bounded_release_chain_v1(rel,'sha256:'||repeat('9',64),12) IS NOT NULL THEN RAISE EXCEPTION 'TAMPERED_RECEIPT_CHAIN_ACCEPTED';END IF;\nEND $test$;\nSELECT 'CHAT_APPROVAL_AND_SUCCESSIVE_BOUNDED_RECEIPT_CONTINUATION_VERIFIED';\nROLLBACK;\n";
const r=spawnSync('psql',['-X','-q','-v','ON_ERROR_STOP=1','-At'],{encoding:'utf8',input:[setup,initial,bounded,chat,chain,stage,scenario].join('\n')});
assert.equal(r.status,0,r.stderr);
assert.match(r.stdout,/CHAT_APPROVAL_AND_SUCCESSIVE_BOUNDED_RECEIPT_CONTINUATION_VERIFIED/);
console.log(r.stdout.trim());
